mapper.select:
select distinct u.user_id as userId, u.dept_id as deptId, coalesce(d.dept_name, '未分配组织') as deptName from sys_user u left join sys_dept d on d.dept_id = u.dept_id and d.del_flag = '0' where u.del_flag = '0' and u.status = '0' and (
1 = 1
u.user_id = #{audience.targetId}
exists (select 1 from sys_user_role ur where ur.user_id = u.user_id and ur.role_id = #{audience.targetId})
(u.dept_id = #{audience.targetId} or find_in_set(#{audience.targetId}, d.ancestors))
u.dept_id = #{audience.targetId}
) order by u.user_id

select u.user_id as id, u.nick_name as label, concat(coalesce(d.dept_name, '未分配组织'), ' / ', u.user_name) as description from sys_user u left join sys_dept d on d.dept_id = u.dept_id and d.del_flag = '0' where u.del_flag = '0' and u.status = '0'
and (u.user_name like concat('%', #{keyword}, '%') or u.nick_name like concat('%', #{keyword}, '%') or d.dept_name like concat('%', #{keyword}, '%'))
order by u.user_id limit #{limit}
